mapper.select:
select smc.monitor_code, smc.monitor_name, smc.alarm_type, iaf.min_char, iaf.min_num, iaf.max_char, iaf.max_num, iac.tenant_id, iac.app_ver_code, iac.industry_code, iad.device_code, iaf.id from vm_sensor_monitor_config smc INNER JOIN vm_iot_alarm_factor_t iaf on smc.monitor_code = iaf.factor_code INNER JOIN vm_iot_alarm_config_t iac on iaf.config_id = iac.id INNER JOIN vm_iot_alarm_device_t iad on iad.group_id = iac.id where iac.config_status = '1' and iac.delete_flag = '0' and smc.delete_flag = '0' and iaf.delete_flag = '0' and iac.config_method = #{param.configMethod} and iad.delete_flag = '0' and iad.device_code in
#{deviceCode}
and smc.monitor_code in
#{monitorCode}
and iac.tenant_id in
#{tenantId}

select smc.monitor_code, smc.monitor_name, smc.alarm_type, iaf.min_char, iaf.min_num, iaf.max_char, iaf.max_num, iac.tenant_id, iac.app_ver_code, iac.industry_code, iaf.id from vm_sensor_monitor_config smc INNER JOIN vm_iot_alarm_factor_t iaf on smc.monitor_code = iaf.factor_code INNER JOIN vm_iot_alarm_config_t iac on iaf.config_id = iac.id where iac.config_status = '1' and iac.delete_flag = '0' and smc.delete_flag = '0' and iaf.delete_flag = '0' and iac.config_method = #{param.configMethod}
and smc.monitor_code in
#{monitorCode}
and iac.tenant_id in
#{tenantId}
